/**
 * The full view of one entity (`design/archetypes/detail-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/detail-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input, output } from '@angular/core'

import { MEMBER_PROVIDERS, SlotOutlet, SlotTemplate, useMember } from '@polymorph/angular'
import styles from '@polymorph/recipes/archetypes/detail-page.module.css'
import { Button, type ButtonProps } from '../controls/Button'

/** The full view of one entity: the inputs it takes, by the React member's prop names. */
export interface DetailPageProps {
  backLabel: string
  /**
   * Keeps the aside in view while the main column scrolls, at the widths where it is beside the
   * main column. It is never taller than the visible box and scrolls inside itself when it is
   * longer. Default `false`: the aside scrolls with the page.
   */
  stickyAside?: boolean
  /**
   * The entity's name, rendered as the page's `<h1>`.
   */
  title: string
}

/** The full view of one entity. */
@Component({
  selector: 'pm-detail-page',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [SlotOutlet, SlotTemplate, Button],
  // prettier-ignore
  template: `<ng-template pmSlot="actions" [pmSlotOf]="$"><ng-content select="[slot=actions]" /></ng-template>
<ng-template pmSlot="aside" [pmSlotOf]="$"><ng-content select="[slot=aside]" /></ng-template>
<ng-template pmSlot="meta" [pmSlotOf]="$"><ng-content select="[slot=meta]" /></ng-template>
<ng-template pmSlot="tabs" [pmSlotOf]="$"><ng-content select="[slot=tabs]" /></ng-template>
<ng-template pmSlot="titleEdit" [pmSlotOf]="$"><ng-content select="[slot=titleEdit]" /></ng-template>
<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<div
[attr.class]="e1()"
data-member="detail-page"
><!-- back -->
<div
[attr.class]="e2()"
><pm-button
variant="ghost"
tone="neutral"
size="sm"
icon="back"
[label]="e3()"
(click)="h1()"
></pm-button></div>
<!-- header -->
<div
[attr.class]="e4()"
><!-- identity -->
<div
[attr.class]="e5()"
>@if (e6()) {<!-- titleRow -->
<div
[attr.class]="e7()"
><!-- title -->
<h1
[attr.class]="e8()"
>{{ e9() }}</h1>
<!-- titleEdit -->
<div
[attr.class]="e10()"
><ng-container [pmSlotOutlet]="'titleEdit'" [pmSlotOf]="$" /></div></div>} @else {<!-- title -->
<h1
[attr.class]="e11()"
>{{ e12() }}</h1>}
@if (e13()) {<!-- meta -->
<div
[attr.class]="e14()"
><ng-container [pmSlotOutlet]="'meta'" [pmSlotOf]="$" /></div>}</div>
@if (e15()) {<!-- actions -->
<div
[attr.class]="e16()"
><ng-container [pmSlotOutlet]="'actions'" [pmSlotOf]="$" /></div>}</div>
<ng-container [pmSlotOutlet]="'tabs'" [pmSlotOf]="$" />
@if (e17()) {<!-- body -->
<div
[attr.class]="e18()"
[attr.data-aside]="e19()"
[attr.data-sticky-aside]="e20()"
><!-- main -->
<div
[attr.class]="e21()"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></div>
@if (e22()) {<!-- aside -->
<div
[attr.class]="e23()"
><ng-container [pmSlotOutlet]="'aside'" [pmSlotOf]="$" /></div>}</div>}</div>`,
})
export class DetailPage {
  readonly backLabel = input.required<DetailPageProps['backLabel']>()
  /**
   * Keeps the aside in view while the main column scrolls, at the widths where it is beside the
   * main column. It is never taller than the visible box and scrolls inside itself when it is
   * longer. Default `false`: the aside scrolls with the page.
   */
  readonly stickyAside = input<
    Exclude<DetailPageProps['stickyAside'], undefined>,
    DetailPageProps['stickyAside']
  >(false, {
    transform: (value: DetailPageProps['stickyAside']) => (value === undefined ? false : value),
  })
  /**
   * The entity's name, rendered as the page's `<h1>`.
   */
  readonly title = input.required<DetailPageProps['title']>()
  readonly onBack = output<void>({ alias: 'back' })
  protected readonly $ = useMember({
    events: ['back'],
    props: {
      backLabel: () => this.backLabel(),
      stickyAside: () => this.stickyAside(),
      title: () => this.title(),
    },
  })
  protected readonly $p = this.$.props

  constructor() {
    this.$.pass('titleEdit', () => ({ valueHidden: true }))
  }

  protected e1() {
    return styles.page
  }

  protected e2() {
    return styles.back
  }

  protected e3(): ButtonProps['label'] {
    return this.$p.backLabel
  }

  protected h1(): void {
    this.$.emit(this.onBack, 'onBack')
  }

  protected e4() {
    return styles.header
  }

  protected e5() {
    return styles.identity
  }

  protected e6() {
    return this.$.filled('titleEdit')
  }

  protected e7() {
    if (!this.$.filled('titleEdit')) return undefined as never
    return styles.titleRow
  }

  protected e8() {
    if (!this.$.filled('titleEdit')) return undefined as never
    return styles.title
  }

  protected e9() {
    if (!this.$.filled('titleEdit')) return undefined as never
    return this.$p.title
  }

  protected e10() {
    if (!this.$.filled('titleEdit')) return undefined as never
    return styles.titleEdit
  }

  protected e11() {
    if (this.$.filled('titleEdit')) return undefined as never
    return styles.title
  }

  protected e12() {
    if (this.$.filled('titleEdit')) return undefined as never
    return this.$p.title
  }

  protected e13() {
    return this.$.filled('meta')
  }

  protected e14() {
    if (!this.$.filled('meta')) return undefined as never
    return styles.meta
  }

  protected e15() {
    return this.$.filled('actions')
  }

  protected e16() {
    if (!this.$.filled('actions')) return undefined as never
    return styles.actions
  }

  protected e17() {
    return this.$.filled('default') || this.$.filled('aside')
  }

  protected e18() {
    if (!(this.$.filled('default') || this.$.filled('aside'))) return undefined as never
    return styles.body
  }

  protected e19() {
    if (!(this.$.filled('default') || this.$.filled('aside'))) return undefined as never
    return this.$.filled('aside') ? '' : undefined
  }

  protected e20() {
    if (!(this.$.filled('default') || this.$.filled('aside'))) return undefined as never
    return this.$.filled('aside') && this.$p.stickyAside ? '' : undefined
  }

  protected e21() {
    if (!(this.$.filled('default') || this.$.filled('aside'))) return undefined as never
    return styles.main
  }

  protected e22() {
    if (!(this.$.filled('default') || this.$.filled('aside'))) return undefined as never
    return this.$.filled('aside')
  }

  protected e23() {
    if (!(this.$.filled('default') || this.$.filled('aside'))) return undefined as never
    if (!this.$.filled('aside')) return undefined as never
    return styles.aside
  }
}
